3	import { use, useEffect, useState } from "react";
4	import Link from "next/link";
5	import { notFound, useRouter } from "next/navigation";
6	import { PageHeader } from "@/components/page-header";
7	import { Card, CardContent } from "@repo/ui/components/card";
8	import { Button } from "@repo/ui/components/button";
9	import { Badge } from "@repo/ui/components/badge";
10	import { Separator } from "@repo/ui/components/separator";
11	import { RiskBadge, StatusBadge } from "@/components/badges";
12	import { useToast } from "@/components/toaster";
13	import { api, ApiError, friendlyApiError } from "@/lib/api";
14	import { emit } from "@/lib/bus";
15	import type { Property, Ticket, Vendor } from "@/lib/types";
16	import { formatEur, timeAgo } from "@/lib/utils";
17	import { cn } from "@repo/ui/lib/utils";
18	import {
19	  Phone, Mail, ChevronDown, ChevronRight, Check, Sparkles,
20	  CheckCircle2, Clock, MessageSquare, Wrench, FileEdit, Loader2,
21	} from "lucide-react";
22	
23	type Mutation = "approve" | "reject" | "saveMemory" | "skipMemory";
24	
25	export default function TicketDetailPage({ params }: { params: Promise<{ id: string }> }) {
26	  const { id } = use(params);
27	  const router = useRouter();
28	  const { push: pushToast } = useToast();
29	
30	  const [t, setTicket] = useState<Ticket | null>(null);
31	  const [prop, setProp] = useState<Property | null>(null);
32	  const [vendor, setVendor] = useState<Vendor | null>(null);
33	  const [loadError, setLoadError] = useState<string | null>(null);
34	  const [mutating, setMutating] = useState<Mutation | null>(null);
35	
36	  const [transcriptOpen, setTranscriptOpen] = useState(false);
37	  const [reasoningOpen, setReasoningOpen] = useState(false);
38	
39	  useEffect(() => {
40	    let cancelled = false;
41	    setTicket(null);
42	    setProp(null);
43	    setVendor(null);
44	    setLoadError(null);
45	    (async () => {
46	      try {
47	        const ticket = await api.tickets.get(id);
48	        if (cancelled) return;
49	        setTicket(ticket);
50	        const [property, v] = await Promise.all([
51	          api.properties.get(ticket.propertyId),
52	          ticket.proposal ? api.vendors.get(ticket.proposal.proposedAction.vendorId) : Promise.resolve(null),
53	        ]);
54	        if (cancelled) return;
55	        setProp(property);
56	        setVendor(v);
57	      } catch (err) {
58	        if (cancelled) return;
59	        if (err instanceof ApiError && err.status === 404) {
60	          notFound();
61	          return;
62	        }
63	        setLoadError(err instanceof Error ? err.message : "Failed to load ticket");
64	      }
65	    })();
66	    return () => { cancelled = true; };
67	  }, [id]);
68	
69	  async function runMutation(
70	    kind: Mutation,
71	    fn: () => Promise<void>,
72	  ) {
73	    setMutating(kind);
74	    try {
75	      await fn();
76	    } catch (err) {
77	      const friendly = friendlyApiError(err, kind);
78	      pushToast({ ...friendly, variant: "destructive" });
79	    } finally {
80	      setMutating(null);
81	    }
82	  }
83	
84	  async function refetchTicket(): Promise<Ticket | null> {
85	    try {
86	      const fresh = await api.tickets.get(id);
87	      setTicket(fresh);
88	      return fresh;
89	    } catch (err) {
90	      const friendly = friendlyApiError(err, "load");
91	      pushToast({ ...friendly, variant: "destructive" });
92	      return null;
93	    }
94	  }
95	
96	  async function handleApprove() {
97	    if (!t) return;
98	    await runMutation("approve", async () => {
99	      await api.tickets.approve(t.id);
100	      const fresh = await refetchTicket();
101	      pushToast({
102	        title: "Dispatch approved",
103	        description: fresh?.vendorJob ? `SLA timer started · status ${fresh.status}` : "SMS sent to vendor.",
104	        variant: "success",
105	      });
106	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
107	      router.refresh();
108	    });
109	  }
110	
111	  async function handleReject() {
112	    if (!t) return;
113	    await runMutation("reject", async () => {
114	      await api.tickets.reject(t.id);
115	      await refetchTicket();
116	      pushToast({ title: "Proposal rejected" });
117	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
118	      router.refresh();
119	    });
120	  }
121	
122	  async function handleSaveMemory() {
123	    if (!t || !t.memoryProposal) return;
124	    await runMutation("saveMemory", async () => {
125	      const result = await api.tickets.saveMemory(t.id);
126	      await refetchTicket();
127	      pushToast({
128	        title: "Memory saved",
129	        description: `context.md bumped to v${result.contextVersion}`,
130	        variant: "success",
131	      });
132	      emit({ kind: "context-bumped", propertyId: t.propertyId, version: result.contextVersion });
133	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
134	      router.refresh();
135	    });
136	  }
137	
138	  async function handleSkipMemory() {
139	    if (!t || !t.memoryProposal) return;
140	    await runMutation("skipMemory", async () => {
141	      await api.tickets.skipMemory(t.id);
142	      await refetchTicket();
143	      pushToast({ title: "Memory write skipped" });
144	      emit({ kind: "ticket-changed", ticketId: t.id, propertyId: t.propertyId });
145	      router.refresh();
146	    });
147	  }
148	
149	  if (loadError) {
150	    return <div className="p-8 text-sm text-destructive">{loadError}</div>;
151	  }
152	  if (!t) {
153	    return <TicketDetailSkeleton />;
154	  }
155	
156	  const isApproved = t.status !== "proposed" && t.status !== "new" && t.status !== "triaged" && t.status !== "rejected";
157	  const memorySaved = t.memoryProposal?.status === "saved";
158	  const memorySkipped = t.memoryProposal?.status === "skipped";
159	  const showMemoryDecision =
160	    !!t.memoryProposal &&
161	    t.memoryProposal.status === "pending" &&
162	    !!t.vendorJob?.completedAt;
163	
164	  return (
165	    <div>
166	      <PageHeader
167	        title={t.subject}
168	        subtitle={`${prop?.name ?? ""} · ${t.raisedBy} · ${timeAgo(t.createdAt)} ago`}
169	        crumbs={[{ label: "Properties" }, { label: prop?.name ?? "", href: prop ? `/property/${prop.id}/tickets` : undefined }, { label: t.num }]}
170	        actions={
171	          <div className="flex items-center gap-2">
172	            <StatusBadge status={t.status} />
173	            <RiskBadge risk={t.risk} />
174	            <span className="font-mono text-xs text-muted-foreground">{t.num}</span>
175	          </div>
176	        }
177	      />
178	
179	      <div className="grid grid-cols-3 gap-6 p-8">
180	        {/* LEFT 2/3 — proposal-first */}
181	        <div className="col-span-2 space-y-4">
182	          {/* Proposal card (only shown when proposed) */}
183	          {t.proposal && (
184	            <Card className="border-blue-500/30 bg-blue-500/5">
185	              <CardContent className="p-5">
186	                <div className="mb-3 flex items-center justify-between">
187	                  <div className="text-xs font-semibold uppercase tracking-wider text-blue-500 dark:text-blue-400">
188	                    Proposed action <span className="ml-2 font-mono text-muted-foreground">{t.proposal.id}</span>
189	                  </div>
190	                  <Badge variant="muted" className="font-mono">conf {Math.round(t.proposal.confidence * 100)}%</Badge>
191	                </div>
192	
193	                {/* Action — vendor / cost / ETA */}
194	                <div className="mb-4 flex items-start justify-between gap-6">
195	                  <div className="min-w-0 flex-1">
196	                    <div className="text-xl font-semibold">{t.proposal.proposedAction.vendor}</div>
197	                    <div className="text-sm text-muted-foreground">
198	                      {t.proposal.proposedAction.trade} · {t.proposal.proposedAction.target}
199	                    </div>
200	                  </div>
201	                  <div className="flex shrink-0 items-stretch gap-2">
202	                    <div className="rounded-md border bg-background px-3 py-2 text-center">
203	                      <div className="text-lg font-semibold leading-none">{formatEur(t.proposal.proposedAction.estimateEur)}</div>
204	                      <div className="mt-1 text-[10px] text-muted-foreground">estimate</div>
205	                    </div>
206	                    <div className="rounded-md border bg-background px-3 py-2 text-center">
207	                      <div className="text-lg font-semibold leading-none">{t.proposal.proposedAction.etaHours}h</div>
208	                      <div className="mt-1 text-[10px] text-muted-foreground">ETA</div>
209	                    </div>
210	                  </div>
211	                </div>
212	
213	                {/* Policy chips */}
214	                <div className="mb-4 flex flex-wrap gap-1.5">
215	                  {t.proposal.policiesEvaluated.map((p) => (
216	                    <Badge key={p.code} variant={p.passed ? "success" : "destructive"} className="font-normal">
217	                      {p.passed ? "✓" : "✗"} {p.name}
218	                    </Badge>
219	                  ))}
220	                </div>
221	
222	                {/* Consequences */}
223	                <div className="mb-4 rounded-md border border-emerald-500/30 bg-emerald-500/8 p-4">
224	                  <div className="mb-2 text-[10px] font-semibold uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Approving will:</div>
225	                  <ul className="space-y-1.5 text-sm">
226	                    <li className="flex gap-2"><span>→</span><span>Dispatch <strong>{t.proposal.proposedAction.vendor}</strong> to {t.proposal.proposedAction.target}</span></li>
227	                    <li className="flex gap-2"><span>→</span><span>Send written confirmation to {t.raisedBy} <em>(Sie-Form, mobility flag respected)</em></span></li>
228	                    <li className="flex gap-2"><span>→</span><span>Send SMS dispatch to {vendor?.name ?? t.proposal.proposedAction.vendor} ({vendor?.phone ?? "—"}) — {vendor?.slaHours ?? t.proposal.proposedAction.etaHours}h SLA timer starts</span></li>
229	                    <li className="flex gap-2 text-muted-foreground"><span>→</span><span>Memory write happens <strong>after</strong> vendor reports completion (not now)</span></li>
230	                  </ul>
231	                </div>
232	
233	                {/* Action row */}
234	                {!isApproved && t.status === "proposed" ? (
235	                  <div className="flex items-center gap-2">
236	                    <Button
237	                      variant="success"
238	                      className="flex-1"
239	                      onClick={handleApprove}
240	                      disabled={mutating !== null}
241	                    >
242	                      {mutating === "approve" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
243	                      Approve dispatch
244	                    </Button>
245	                    <Button variant="outline" disabled={mutating !== null}>Edit</Button>
246	                    <Button
247	                      variant="ghost"
248	                      className="text-red-600 hover:bg-red-50 hover:text-red-700"
249	                      onClick={handleReject}
250	                      disabled={mutating !== null}
251	                    >
252	                      {mutating === "reject" ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
253	                      Reject
254	                    </Button>
255	                  </div>
256	                ) : isApproved ? (
257	                  <div className="rounded-md border border-emerald-500/40 bg-emerald-500/10 p-3 text-sm">
258	                    <div className="flex items-center gap-2 font-medium text-emerald-600 dark:text-emerald-400">
259	                      <CheckCircle2 className="h-4 w-4" />
260	                      Dispatch approved · SMS sent to {vendor?.name ?? t.proposal.proposedAction.vendor} · Email sent to {t.raisedBy}
261	                    </div>
262	                    <div className="mt-1 text-xs text-emerald-600/80 dark:text-emerald-400/80">
263	                      SLA timer started ({vendor?.slaHours ?? t.proposal.proposedAction.etaHours}h). Status: <strong>{t.status}</strong>. No memory write yet.
264	                    </div>
265	                  </div>
266	                ) : t.status === "rejected" ? (
267	                  <div className="rounded-md border border-destructive/40 bg-destructive/5 p-3 text-sm text-destructive">
268	                    Proposal rejected.
269	                  </div>
270	                ) : null}
271	
272	                {/* Reasoning collapsed by default */}
273	                <button
274	                  onClick={() => setReasoningOpen((o) => !o)}
275	                  className="mt-4 flex w-full items-center justify-between rounded-md border-t pt-3 text-left text-sm hover:bg-accent/50"
276	                >
277	                  <span className="font-medium">Reasoning & evidence <span className="ml-1 font-mono text-xs text-muted-foreground">cites context.md v{t.proposal.contextVersion}</span></span>
278	                  {reasoningOpen ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
279	                </button>
280	                {reasoningOpen && (
281	                  <div className="mt-3 space-y-3 text-sm">
282	                    <p className="text-muted-foreground">{t.proposal.reasoning}</p>
283	                    <div className="space-y-2">
284	                      {t.proposal.citations.map((c, i) => (
285	                        <div key={i} className="rounded border-l-2 border-blue-300 bg-background px-3 py-2">
286	                          <div className="text-[10px] font-semibold uppercase tracking-wider text-muted-foreground">{c.heading}</div>
287	                          <div className="text-sm">{c.excerpt}</div>
288	                        </div>
289	                      ))}
290	                    </div>
291	                  </div>
292	                )}
293	              </CardContent>
294	            </Card>
295	          )}
296	
297	          {/* Vendor job status (when in flight or completed) */}
298	          {t.vendorJob && (
299	            <Card>
300	              <CardContent className="p-5">
301	                <div className="mb-3 flex items-center gap-2">
302	                  <Wrench className="h-4 w-4 text-muted-foreground" />
303	                  <h3 className="text-sm font-semibold">Vendor job</h3>
304	                </div>
305	                <ul className="space-y-2 text-sm">
306	                  <li className="flex justify-between"><span className="text-muted-foreground">Sent</span><span>{new Date(t.vendorJob.sentAt).toLocaleString("de-DE")}</span></li>
307	                  <li className="flex justify-between"><span className="text-muted-foreground">Accepted</span><span>{t.vendorJob.accepted ? "Yes" : "Pending"}</span></li>
308	                  {t.vendorJob.scheduledFor && <li className="flex justify-between"><span className="text-muted-foreground">Scheduled</span><span>{new Date(t.vendorJob.scheduledFor).toLocaleString("de-DE")}</span></li>}
309	                  {t.vendorJob.completedAt && <li className="flex justify-between"><span className="text-muted-foreground">Completed</span><span>{new Date(t.vendorJob.completedAt).toLocaleString("de-DE")}</span></li>}
310	                  {t.vendorJob.finalCostEur != null && <li className="flex justify-between"><span className="text-muted-foreground">Final cost</span><span className="font-medium">{formatEur(t.vendorJob.finalCostEur)}</span></li>}
311	                  {t.vendorJob.notes && <li className="text-muted-foreground">"{t.vendorJob.notes}"</li>}
312	                </ul>
313	              </CardContent>
314	            </Card>
315	          )}
316	
317	          {/* MEMORY DECISION — only after vendor completion AND status === pending */}
318	          {showMemoryDecision && (
319	            <Card className="border-emerald-500/30 bg-emerald-500/5">
320	              <CardContent className="p-5">
321	                <div className="mb-2 flex items-center gap-2">
322	                  <Sparkles className="h-4 w-4 text-emerald-500" />
323	                  <div className="text-xs font-semibold uppercase tracking-wider text-emerald-600 dark:text-emerald-400">Memory decision · vendor closed the job</div>
324	                </div>
325	                <p className="mb-3 text-sm">
326	                  Save to <code className="font-mono text-xs">context.md v{t.memoryProposal!.targetVersion}</code>:
327	                </p>
328	                <blockquote className="mb-4 rounded border-l-2 border-emerald-400 bg-background px-3 py-2 text-sm">
329	                  {t.memoryProposal!.text}
330	                </blockquote>
331	                <div className="flex gap-2">
332	                  <Button variant="success" onClick={handleSaveMemory} disabled={mutating !== null}>
333	                    {mutating === "saveMemory" ? <Loader2 className="h-4 w-4 animate-spin" /> : <Check className="h-4 w-4" />}
334	                    Save to memory
335	                  </Button>
336	                  <Button variant="outline" disabled={mutating !== null}><FileEdit className="h-4 w-4" />Edit</Button>
337	                  <Button variant="ghost" onClick={handleSkipMemory} disabled={mutating !== null}>
338	                    {mutating === "skipMemory" ? <Loader2 className="h-4 w-4 animate-spin" /> : null}
339	                    Skip
340	                  </Button>
341	                </div>
342	              </CardContent>
343	            </Card>
344	          )}
345	
346	          {memorySaved && (
347	            <Card className="border-emerald-500/40 bg-emerald-500/10">
348	              <CardContent className="p-4 text-sm text-emerald-600 dark:text-emerald-400">
349	                <CheckCircle2 className="mr-2 inline h-4 w-4" />
350	                Memory saved to <code className="font-mono text-xs">context.md v{t.memoryProposal?.targetVersion}</code>. Ticket resolved.
351	              </CardContent>
352	            </Card>
353	          )}
354	
355	          {memorySkipped && (
356	            <Card>
357	              <CardContent className="p-4 text-sm text-muted-foreground">
358	                Memory write skipped. Ticket closed without context update.
359	              </CardContent>
360	            </Card>
361	          )}
362	
363	          {/* SOURCE — call transcript or email */}
364	          {t.callSession && (
365	            <Card>
366	              <CardContent className="p-5">
367	                <button
368	                  onClick={() => setTranscriptOpen((o) => !o)}
369	                  className="flex w-full items-center justify-between text-left"
370	                >
371	                  <div className="flex items-center gap-2">
372	                    <Phone className="h-4 w-4 text-muted-foreground" />
373	                    <span className="text-sm font-semibold">Call transcript</span>
374	                    <Badge variant="muted" className="font-mono">{t.callSession.duration}</Badge>
375	                    <span className="text-xs text-muted-foreground">noise reduction {t.callSession.noiseReductionDb} dB</span>
376	                  </div>
377	                  {transcriptOpen ? <ChevronDown className="h-4 w-4" /> : <ChevronRight className="h-4 w-4" />}
378	                </button>
379	                {!transcriptOpen && (
380	                  <p className="mt-2 text-sm text-muted-foreground">{t.callSession.summary}</p>
381	                )}
382	                {transcriptOpen && (
383	                  <div className="mt-4 space-y-2 max-h-80 overflow-auto rounded border bg-muted/20 p-3">
384	                    {t.callSession.transcript.map((line, i) => (
385	                      <div key={i} className={cn("flex gap-3 text-sm", line.spk === "tenant" ? "" : "text-muted-foreground")}>
386	                        <span className="w-12 shrink-0 font-mono text-[10px] text-muted-foreground">{line.t}</span>
387	                        <span className="w-14 shrink-0 text-[10px] uppercase">{line.spk}</span>
388	                        <div className="flex-1">
389	                          <div>{line.text}</div>
390	                          <div className="text-[11px] italic text-muted-foreground">{line.en}</div>
391	                        </div>
392	                      </div>
393	                    ))}
394	                  </div>
395	                )}
396	              </CardContent>
397	            </Card>
398	          )}
399	
400	          {t.emailBody && (
401	            <Card>
402	              <CardContent className="p-5">
403	                <div className="mb-2 flex items-center gap-2">
404	                  <Mail className="h-4 w-4 text-muted-foreground" />
405	                  <span className="text-sm font-semibold">Email</span>
406	                </div>
407	                <pre className="whitespace-pre-wrap text-sm font-sans">{t.emailBody}</pre>
408	              </CardContent>
409	            </Card>
410	          )}
411	        </div>
412	
413	        {/* RIGHT 1/3 — context */}
414	        <aside className="space-y-4">
415	          <Card>
416	            <CardContent className="p-4">
417	              <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Property</div>
418	              <Link href={prop ? `/property/${prop.id}/context` : "#"} className="mt-1 block text-sm font-medium hover:underline">
419	                {prop?.name ?? "—"}
420	              </Link>
421	              <div className="mt-1 text-xs text-muted-foreground">context.md v{prop?.contextVersion ?? "—"}</div>
422	              <Separator className="my-3" />
423	              <div className="space-y-1 text-xs">
424	                <div><span className="text-muted-foreground">Phone: </span>{prop?.phone ?? "—"}</div>
425	                <div><span className="text-muted-foreground">Email: </span>{prop?.email ?? "—"}</div>
426	                <div><span className="text-muted-foreground">Open tickets: </span>{prop?.openTickets ?? "—"}</div>
427	              </div>
428	            </CardContent>
429	          </Card>
430	
431	          <Card>
432	            <CardContent className="p-4">
433	              <div className="text-xs font-semibold uppercase tracking-wider text-muted-foreground">Activity</div>
434	              <ul className="mt-2 space-y-2 text-xs">
435	                <li className="flex gap-2"><Clock className="mt-0.5 h-3 w-3 text-muted-foreground" /><span>Ticket opened — {timeAgo(t.createdAt)} ago</span></li>
436	                <li className="flex gap-2"><MessageSquare className="mt-0.5 h-3 w-3 text-muted-foreground" /><span>Triage agent classified</span></li>
437	                {t.proposal && <li className="flex gap-2"><Sparkles className="mt-0.5 h-3 w-3 text-blue-500 dark:text-blue-400" /><span>Hermes proposed action</span></li>}
