1	import type {
2	  Building, Layer, Owner, Property, PropertyContext, Ticket, Unit, Vendor,
3	} from "./types";
4	
5	const BASE =
6	  (typeof process !== "undefined" && process.env?.NEXT_PUBLIC_BACKEND_URL) ||
7	  "http://localhost:8000";
8	
9	export interface ApiErrorEnvelope {
10	  error: string;
11	  code: string;
12	  status: number;
13	}
14	
15	export class ApiError extends Error {
16	  readonly code: string;
17	  readonly status: number;
18	  readonly path: string;
19	  constructor(envelope: ApiErrorEnvelope, path: string) {
20	    super(envelope.error);
21	    this.name = "ApiError";
22	    this.code = envelope.code;
23	    this.status = envelope.status;
24	    this.path = path;
25	  }
26	}
27	
28	export type ApiAction =
29	  | "approve" | "reject" | "saveMemory" | "skipMemory"
30	  | "extract" | "chat" | "load";
31	
32	export function friendlyApiError(err: unknown, action?: ApiAction): { title: string; description?: string } {
33	  if (err instanceof ApiError) {
34	    if (err.code === "CONFLICT" && action === "saveMemory") {
35	      return {
36	        title: "Memory write blocked",
37	        description: "Vendor hasn't reported completion yet — we don't write memory until the job closes.",
38	      };
39	    }
40	    if (err.code === "CONFLICT") {
41	      return { title: "Action blocked", description: err.message };
42	    }
43	    if (err.code === "VALIDATION_ERROR") {
44	      return { title: "Invalid request", description: err.message };
45	    }
46	    if (err.code === "UNAUTHORIZED") {
47	      return { title: "Sign-in required", description: err.message };
48	    }
49	    if (err.code === "NOT_FOUND") {
50	      return { title: "Not found", description: err.message };
51	    }
52	    return { title: "Request failed", description: err.message };
53	  }
54	  if (err instanceof DOMException && err.name === "AbortError") {
55	    return { title: "Cancelled" };
56	  }
57	  return {
58	    title: "Unexpected error",
59	    description: err instanceof Error ? err.message : String(err),
60	  };
61	}
62	
63	type FetchInit = Omit<RequestInit, "body"> & {
64	  query?: Record<string, string | number | boolean | undefined | null>;
65	  body?: unknown;
66	};
67	
68	function buildUrl(path: string, query?: FetchInit["query"]): string {
69	  const url = new URL(path.startsWith("http") ? path : `${BASE}${path}`);
70	  if (query) {
71	    for (const [k, v] of Object.entries(query)) {
72	      if (v === undefined || v === null) continue;
73	      url.searchParams.set(k, String(v));
74	    }
75	  }
76	  return url.toString();
77	}
78	
79	async function request<T>(path: string, init: FetchInit = {}): Promise<T> {
80	  const { query, body, headers, ...rest } = init;
81	  const url = buildUrl(path, query);
82	
83	  const res = await fetch(url, {
84	    ...rest,
85	    headers: {
86	      "Accept": "application/json",
87	      ...(body !== undefined ? { "Content-Type": "application/json" } : {}),
88	      ...headers,
89	    },
90	    body: body === undefined ? undefined : JSON.stringify(body),
91	  });
92	
93	  if (!res.ok) {
94	    let envelope: ApiErrorEnvelope = {
95	      error: res.statusText || "Request failed",
96	      code: "HTTP_ERROR",
97	      status: res.status,
98	    };
99	    try {
100	      const parsed = await res.json();
101	      if (parsed && typeof parsed === "object" && "error" in parsed) {
102	        envelope = {
103	          error: String((parsed as ApiErrorEnvelope).error ?? envelope.error),
104	          code: String((parsed as ApiErrorEnvelope).code ?? envelope.code),
105	          status: Number((parsed as ApiErrorEnvelope).status ?? res.status),
106	        };
107	      }
108	    } catch {
109	      /* non-JSON error body */
110	    }
111	    throw new ApiError(envelope, path);
112	  }
113	
114	  if (res.status === 204) return undefined as unknown as T;
115	  return res.json() as Promise<T>;
116	}
117	
118	// ---------- modules ----------
119	
120	export const tickets = {
121	  list: (params?: { propertyId?: string; status?: string; risk?: string }) =>
122	    request<Ticket[]>("/api/tickets", { query: params }),
123	  get: (id: string) =>
124	    request<Ticket>(`/api/tickets/${encodeURIComponent(id)}`),
125	  approve: (id: string) =>
126	    request<{ status: string; vendorJob: Ticket["vendorJob"] }>(
127	      `/api/tickets/${encodeURIComponent(id)}/approve`,
128	      { method: "POST", body: {} }
129	    ),
130	  reject: (id: string, reason?: string) =>
131	    request<{ status: string }>(
132	      `/api/tickets/${encodeURIComponent(id)}/reject`,
133	      { method: "POST", body: { reason } }
134	    ),
135	  saveMemory: (id: string) =>
136	    request<{ status: "saved"; contextVersion: number }>(
137	      `/api/tickets/${encodeURIComponent(id)}/memory/save`,
138	      { method: "POST", body: {} }
139	    ),
140	  skipMemory: (id: string) =>
141	    request<{ status: "skipped" }>(
142	      `/api/tickets/${encodeURIComponent(id)}/memory/skip`,
143	      { method: "POST", body: {} }
144	    ),
145	};
146	
147	export const properties = {
148	  list: () => request<Property[]>("/api/properties"),
149	  get: (id: string) => request<Property>(`/api/properties/${encodeURIComponent(id)}`),
150	  units: (id: string) =>
151	    request<Unit[]>(`/api/properties/${encodeURIComponent(id)}/units`),
152	};
153	
154	export const context = {
155	  get: (propertyId: string) =>
156	    request<PropertyContext>(`/api/properties/${encodeURIComponent(propertyId)}/context`),
157	  versions: (propertyId: string) =>
158	    request<Array<{ version: number; createdAt: string; author: string; summary: string }>>(
159	      `/api/properties/${encodeURIComponent(propertyId)}/context/versions`
160	    ),
161	  version: (propertyId: string, version: number) =>
162	    request<PropertyContext>(
163	      `/api/properties/${encodeURIComponent(propertyId)}/context/versions/${version}`
164	    ),
165	};
166	
167	export const owners = {
168	  list: () => request<Owner[]>("/api/owners"),
169	  get: (id: string) => request<Owner>(`/api/owners/${encodeURIComponent(id)}`),
170	};
171	
172	export const buildings = {
173	  list: () => request<Building[]>("/api/buildings"),
174	  get: (id: string) => request<Building>(`/api/buildings/${encodeURIComponent(id)}`),
175	};
176	
177	export const vendors = {
178	  list: (params?: { buildingId?: string }) =>
179	    request<Vendor[]>("/api/vendors", { query: params }),
180	  get: (id: string) =>
181	    request<Vendor & { cases: Array<{ id: string; propertyId: string; date: string; description: string; costEur: number; slaMet: boolean; rating: number }> }>(
182	      `/api/vendors/${encodeURIComponent(id)}`
183	    ),
184	};
185	
186	export const escalations = {
187	  list: () => request<Ticket[]>("/api/escalations"),
188	};
189	
190	export const dev = {
191	  reset: () =>
192	    request<{ message: string; seed_result: Record<string, unknown> }>(
193	      "/api/dev/reset",
194	      { method: "POST" }
195	    ),
196	};
197	
198	export interface ChatScope {
199	  layer: Layer;
200	  id: string;
201	}
202	
203	export interface ChatStreamHandlers {
204	  onDelta?: (text: string) => void;
205	  onDone?: (payload: { messageId: string; appliedTo: string[] }) => void;
206	  onError?: (err: unknown) => void;
207	  signal?: AbortSignal;
208	}
209	
210	export const chat = {
211	  /**
212	   * SSE streaming chat. POST /api/chat returns text/event-stream.
213	   * Frames are delimited by `\n\n`; each frame has `event:` and `data:` lines.
214	   */
215	  stream: async (
216	    payload: { message: string; propertyId?: string; scope?: ChatScope },
217	    handlers: ChatStreamHandlers
218	  ): Promise<void> => {
219	    const url = buildUrl("/api/chat");
220	    const res = await fetch(url, {
221	      method: "POST",
222	      headers: { "Content-Type": "application/json", "Accept": "text/event-stream" },
223	      body: JSON.stringify(payload),
224	      signal: handlers.signal,
225	    });
226	
227	    if (!res.ok || !res.body) {
228	      const env: ApiErrorEnvelope = {
229	        error: `Chat stream failed (${res.status})`,
230	        code: "HTTP_ERROR",
231	        status: res.status,
232	      };
233	      try {
234	        const parsed = await res.json();
235	        if (parsed && typeof parsed === "object" && "error" in parsed) {
236	          Object.assign(env, parsed);
237	        }
238	      } catch { /* ignore */ }
239	      throw new ApiError(env, "/api/chat");
240	    }
241	
242	    const reader = res.body.getReader();
243	    const decoder = new TextDecoder("utf-8");
244	    let buffer = "";
245	
246	    try {
247	      while (true) {
248	        const { value, done } = await reader.read();
249	        if (done) break;
250	        buffer += decoder.decode(value, { stream: true });
251	
252	        let sep: number;
253	        while ((sep = buffer.indexOf("\n\n")) !== -1) {
254	          const frame = buffer.slice(0, sep);
255	          buffer = buffer.slice(sep + 2);
256	          parseSseFrame(frame, handlers);
