export const tickets = {
  list: (params?: { propertyId?: string; status?: string; risk?: string }) =>
    request<Ticket[]>("/api/tickets", { query: params }),
  get: (id: string) =>
    request<Ticket>(`/api/tickets/${encodeURIComponent(id)}`),
  approve: (id: string) =>
